// Tile colors
export const COLORS = {
  RED: { name: 'red', hex: '#e74c3c' },
  BLUE: { name: 'blue', hex: '#3498db' },
  BLACK: { name: 'black', hex: '#2c3e50' },
  ORANGE: { name: 'orange', hex: '#e67e22' }
};

// Message for flip reveal (24 characters)
const MESSAGE = "WILL YOU BE MY VALENTINE";

// Create 24 tiles for the puzzle
export const createInitialTiles = () => {
  const tiles = [
    // Run 1: Red 1-2-3-4
    { id: 1, number: 1, color: COLORS.RED },
    { id: 2, number: 2, color: COLORS.RED },
    { id: 3, number: 3, color: COLORS.RED },
    { id: 4, number: 4, color: COLORS.RED },

    // Run 2: Blue 5-6-7-8
    { id: 5, number: 5, color: COLORS.BLUE },
    { id: 6, number: 6, color: COLORS.BLUE },
    { id: 7, number: 7, color: COLORS.BLUE },
    { id: 8, number: 8, color: COLORS.BLUE },

    // Run 3: Black 9-10-11-12
    { id: 9, number: 9, color: COLORS.BLACK },
    { id: 10, number: 10, color: COLORS.BLACK },
    { id: 11, number: 11, color: COLORS.BLACK },
    { id: 12, number: 12, color: COLORS.BLACK },

    // Run 4: Orange 2-3-4-5
    { id: 13, number: 2, color: COLORS.ORANGE },
    { id: 14, number: 3, color: COLORS.ORANGE },
    { id: 15, number: 4, color: COLORS.ORANGE },
    { id: 16, number: 5, color: COLORS.ORANGE },

    // Group 1: All 6s (Red, Blue, Black, Orange)
    { id: 17, number: 6, color: COLORS.RED },
    { id: 18, number: 6, color: COLORS.BLACK },
    { id: 19, number: 6, color: COLORS.ORANGE },

    // Group 2: All 9s (Red, Blue, Orange)
    { id: 20, number: 9, color: COLORS.RED },
    { id: 21, number: 9, color: COLORS.BLUE },
    { id: 22, number: 9, color: COLORS.ORANGE },

    // Extra tiles to make 24
    { id: 23, number: 1, color: COLORS.BLUE },
    { id: 24, number: 1, color: COLORS.BLACK },
  ];

  // Assign letters from message to each tile
  tiles.forEach((tile, index) => {
    tile.letter = MESSAGE[index] || '?';
  });

  return shuffleArray([...tiles]);
};

// Fisher-Yates shuffle
function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

// Color order for sorting
const COLOR_ORDER = {
  'red': 0,
  'blue': 1,
  'orange': 2,
  'black': 3
};

// Sort tiles by number (primary) then color (secondary)
export function sortByNumber(tiles) {
  return [...tiles].sort((a, b) => {
    if (a.number !== b.number) {
      return a.number - b.number;
    }
    return COLOR_ORDER[a.color.name] - COLOR_ORDER[b.color.name];
  });
}

// Sort tiles by color (primary) then number (secondary)
export function sortByColor(tiles) {
  return [...tiles].sort((a, b) => {
    if (a.color.name !== b.color.name) {
      return COLOR_ORDER[a.color.name] - COLOR_ORDER[b.color.name];
    }
    return a.number - b.number;
  });
}

// Check if tiles form a valid run (3+ consecutive numbers, same color)
export function isValidRun(tiles) {
  if (tiles.length < 3) return false;

  // All tiles must be same color
  const color = tiles[0].color.name;
  if (!tiles.every(t => t.color.name === color)) return false;

  // Sort by number and check consecutive
  const sorted = [...tiles].sort((a, b) => a.number - b.number);
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i].number !== sorted[i - 1].number + 1) return false;
  }

  return true;
}

// Check if tiles form a valid group (3-4 same numbers, different colors)
export function isValidGroup(tiles) {
  if (tiles.length < 3 || tiles.length > 4) return false;

  // All tiles must have same number
  const number = tiles[0].number;
  if (!tiles.every(t => t.number === number)) return false;

  // All tiles must have different colors
  const colors = tiles.map(t => t.color.name);
  const uniqueColors = new Set(colors);
  if (uniqueColors.size !== tiles.length) return false;

  return true;
}

// Check if a meld is valid (run or group)
export function isValidMeld(tiles) {
  return isValidRun(tiles) || isValidGroup(tiles);
}

// Validate freeboard - find groups of adjacent tiles and check if valid melds
// For freeboard, we validate rows of tiles that are placed together
export function validateBoard(boardTiles) {
  if (boardTiles.length === 0) {
    return { valid: false, message: 'Place all tiles on the board first!' };
  }

  // Group tiles by row (y position)
  const rows = {};
  boardTiles.forEach(tile => {
    const rowKey = Math.round(tile.y / 90); // Group by approximate row
    if (!rows[rowKey]) rows[rowKey] = [];
    rows[rowKey].push(tile);
  });

  // For each row, find groups of adjacent tiles
  for (const rowKey in rows) {
    const rowTiles = rows[rowKey];
    // Sort by x position
    rowTiles.sort((a, b) => a.x - b.x);

    // Find groups of adjacent tiles (tiles within ~70px of each other)
    const groups = [];
    let currentGroup = [rowTiles[0]];

    for (let i = 1; i < rowTiles.length; i++) {
      const gap = rowTiles[i].x - rowTiles[i - 1].x;
      if (gap < 80) {
        // Adjacent tile
        currentGroup.push(rowTiles[i]);
      } else {
        // New group
        if (currentGroup.length >= 1) {
          groups.push(currentGroup);
        }
        currentGroup = [rowTiles[i]];
      }
    }
    if (currentGroup.length >= 1) {
      groups.push(currentGroup);
    }

    // Validate each group
    for (const group of groups) {
      if (group.length < 3) {
        return {
          valid: false,
          message: `Found a group with only ${group.length} tile(s). Each meld needs at least 3 tiles!`
        };
      }
      if (!isValidMeld(group)) {
        const numbers = group.map(t => t.number).join(', ');
        return {
          valid: false,
          message: `Invalid meld: tiles ${numbers}. Make runs (same color, consecutive) or groups (same number, different colors)!`
        };
      }
    }
  }

  return { valid: true, message: '' };
}

// Validate grid - each row must form a valid meld
export function validateGrid(gridTiles) {
  for (let rowIndex = 0; rowIndex < gridTiles.length; rowIndex++) {
    const row = gridTiles[rowIndex];
    const tilesInRow = row.filter(t => t !== null);

    if (tilesInRow.length === 0) {
      continue; // Empty row is OK if other rows have tiles
    }

    // Check for gaps - tiles must be consecutive (no empty slots between tiles)
    let firstTileIndex = -1;
    let lastTileIndex = -1;
    for (let i = 0; i < row.length; i++) {
      if (row[i] !== null) {
        if (firstTileIndex === -1) firstTileIndex = i;
        lastTileIndex = i;
      }
    }

    // Check if there are gaps
    for (let i = firstTileIndex; i <= lastTileIndex; i++) {
      if (row[i] === null) {
        return {
          valid: false,
          message: `Row ${rowIndex + 1} has gaps! Tiles must be placed next to each other.`
        };
      }
    }

    if (tilesInRow.length < 3) {
      return {
        valid: false,
        message: `Row ${rowIndex + 1} has only ${tilesInRow.length} tile(s). Each row needs at least 3 tiles!`
      };
    }

    if (!isValidMeld(tilesInRow)) {
      const numbers = tilesInRow.map(t => t.number).join(', ');
      return {
        valid: false,
        message: `Row ${rowIndex + 1} is invalid (tiles: ${numbers}). Make runs (same color, consecutive) or groups (same number, different colors)!`
      };
    }
  }

  return { valid: true, message: '' };
}
