import React from 'react';
import Tile from './Tile';

const Rack = ({ tiles, onDragStart, onDragEnd }) => {
  return (
    <div className="rack">
      <div className="rack__label">Your Tiles</div>
      <div className="rack__tiles">
        {tiles.map(tile => (
          <Tile
            key={tile.id}
            tile={tile}
            isFlipped={false}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            sourceType="rack"
          />
        ))}
      </div>
    </div>
  );
};

export default Rack;
