import React, { useState, useEffect } from 'react';
import './valentines.css';
import Grid from './Grid';
import Rack from './Rack';
import Tile from './Tile';
import Confetti from './Confetti';
import { createInitialTiles, validateGrid, sortByNumber, sortByColor } from './gameLogic';

const GAME_STATES = {
  START: 'start',
  PLAYING: 'playing',
  FLIPPING: 'flipping',
  QUESTION: 'question',
  YES: 'yes',
};

const Valentines = () => {
  const [gameState, setGameState] = useState(GAME_STATES.START);
  const [rackTiles, setRackTiles] = useState([]);
  const [gridTiles, setGridTiles] = useState([
    [null, null, null, null, null, null, null, null],
    [null, null, null, null, null, null, null, null],
    [null, null, null, null, null, null, null, null],
    [null, null, null, null, null, null, null, null],
    [null, null, null, null, null, null, null, null],
    [null, null, null, null, null, null, null, null],
  ]);
  const [allTiles, setAllTiles] = useState([]);
  const [noButtonPosition, setNoButtonPosition] = useState({ x: 0, y: 0 });
  const [errorMessage, setErrorMessage] = useState('');
  const [isDragging, setIsDragging] = useState(false);
  const [tilesPlaced, setTilesPlaced] = useState(0);

  useEffect(() => {
    const count = gridTiles.flat().filter(t => t !== null).length;
    setTilesPlaced(count);
  }, [gridTiles]);

  const startGame = () => {
    const tiles = createInitialTiles();
    setAllTiles(tiles);
    setRackTiles(tiles);
    setGridTiles([
      [null, null, null, null, null, null, null, null],
      [null, null, null, null, null, null, null, null],
      [null, null, null, null, null, null, null, null],
      [null, null, null, null, null, null, null, null],
      [null, null, null, null, null, null, null, null],
      [null, null, null, null, null, null, null, null],
    ]);
    setErrorMessage('');
    setGameState(GAME_STATES.PLAYING);
  };

  const handleDragStart = () => {
    setIsDragging(true);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const handleDropToSlot = (tileId, row, col, sourceType, sourceRow, sourceCol) => {
    let tile;
    let newRackTiles = [...rackTiles];
    let newGridTiles = gridTiles.map(r => [...r]);

    // Check if target slot is already occupied
    if (newGridTiles[row][col] !== null) {
      return; // Can't drop on occupied slot
    }

    if (sourceType === 'rack') {
      // Moving from rack to grid
      tile = rackTiles.find(t => t.id === tileId);
      if (!tile) return;
      newRackTiles = rackTiles.filter(t => t.id !== tileId);
      newGridTiles[row][col] = tile;
    } else if (sourceType === 'grid') {
      // Moving within grid
      tile = newGridTiles[sourceRow][sourceCol];
      if (!tile) return;
      newGridTiles[sourceRow][sourceCol] = null;
      newGridTiles[row][col] = tile;
    }

    setRackTiles(newRackTiles);
    setGridTiles(newGridTiles);
    setErrorMessage('');
    setIsDragging(false);
  };

  const handleDropToRack = (e) => {
    e.preventDefault();
    const sourceType = e.dataTransfer.getData('sourceType');

    if (sourceType !== 'grid') return;

    const tileId = parseInt(e.dataTransfer.getData('tileId'), 10);
    const sourceRow = parseInt(e.dataTransfer.getData('sourceRow'), 10);
    const sourceCol = parseInt(e.dataTransfer.getData('sourceCol'), 10);

    const tile = gridTiles[sourceRow]?.[sourceCol];
    if (!tile || tile.id !== tileId) return;

    const newGridTiles = gridTiles.map(r => [...r]);
    newGridTiles[sourceRow][sourceCol] = null;

    setGridTiles(newGridTiles);
    setRackTiles([...rackTiles, tile]);
    setErrorMessage('');
    setIsDragging(false);
  };

  const handleCheckSolution = () => {
    // Check if all tiles are placed
    const placedCount = gridTiles.flat().filter(t => t !== null).length;
    if (placedCount !== allTiles.length) {
      setErrorMessage(`Place all ${allTiles.length} tiles on the grid first! (${placedCount}/${allTiles.length} placed)`);
      return;
    }

    // Validate the grid
    const result = validateGrid(gridTiles);

    if (result.valid) {
      // WIN!
      setGameState(GAME_STATES.FLIPPING);
      setTimeout(() => {
        setGameState(GAME_STATES.QUESTION);
      }, 3000);
    } else {
      setErrorMessage(result.message);
    }
  };

  const handleYes = () => {
    setGameState(GAME_STATES.YES);
  };

  const handleNo = () => {
    setNoButtonPosition({
      x: (Math.random() - 0.5) * 400,
      y: (Math.random() - 0.5) * 300
    });
  };

  const handleSortByNumber = () => {
    setRackTiles(sortByNumber(rackTiles));
  };

  const handleSortByColor = () => {
    setRackTiles(sortByColor(rackTiles));
  };

  // Get all placed tiles in order for the flip animation
  const getOrderedTiles = () => {
    const tiles = [];
    for (let row = 0; row < 6; row++) {
      for (let col = 0; col < 8; col++) {
        if (gridTiles[row][col]) {
          tiles.push(gridTiles[row][col]);
        }
      }
    }
    return tiles;
  };

  return (
    <div className="valentines">
      {/* Floating hearts background */}
      <div className="valentines__bg-hearts">
        {[...Array(6)].map((_, i) => (
          <span key={i} className="valentines__bg-heart" style={{ animationDelay: `${i * 2}s` }}>
            ♥
          </span>
        ))}
      </div>

      {gameState === GAME_STATES.START && (
        <div className="valentines__start">
          <div className="valentines__logo">
            <span className="valentines__logo-icon">🎮</span>
          </div>
          <h1 className="valentines__title">Yuna's Rummikub Challenge</h1>
          <p className="valentines__subtitle">A special puzzle just for you</p>
          <button className="valentines__play-btn" onClick={startGame}>
            <span className="valentines__play-icon">▶</span>
            Start Game
          </button>
          <p className="valentines__hint-text">Solve the puzzle to unlock a surprise!</p>
        </div>
      )}

      {gameState === GAME_STATES.PLAYING && (
        <div className="valentines__game">
          <div className="valentines__header">
            <h2 className="valentines__game-title">Arrange the tiles!</h2>
            <div className="valentines__progress">
              <div className="valentines__progress-bar">
                <div
                  className="valentines__progress-fill"
                  style={{ width: `${(tilesPlaced / 24) * 100}%` }}
                />
              </div>
              <span className="valentines__progress-text">{tilesPlaced}/24</span>
            </div>
          </div>

          <p className="valentines__instructions">
            Create valid melds in each row: <strong>runs</strong> (3+ consecutive numbers, same color)
            or <strong>groups</strong> (3-4 same numbers, different colors)
          </p>

          <Grid
            gridTiles={gridTiles}
            onDropToSlot={handleDropToSlot}
            isDragging={isDragging}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
          />

          <div className="valentines__rack-section">
            <div className="valentines__sort-buttons">
              <button
                className="valentines__sort-btn"
                onClick={handleSortByNumber}
                title="Sort by number"
              >
                <span className="valentines__sort-icon">123</span>
              </button>
              <button
                className="valentines__sort-btn"
                onClick={handleSortByColor}
                title="Sort by color"
              >
                <span className="valentines__sort-icon">🎨</span>
              </button>
            </div>
            <div
              className="rack-drop-zone"
              onDragOver={(e) => e.preventDefault()}
              onDrop={handleDropToRack}
            >
              <Rack
                tiles={rackTiles}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
              />
            </div>
          </div>

          {errorMessage && (
            <p className="valentines__error">{errorMessage}</p>
          )}

          <button
            className={`valentines__check-btn ${tilesPlaced === 24 ? 'valentines__check-btn--ready' : ''}`}
            onClick={handleCheckSolution}
          >
            <span className="valentines__check-icon">✓</span>
          </button>
        </div>
      )}

      {(gameState === GAME_STATES.FLIPPING || gameState === GAME_STATES.QUESTION || gameState === GAME_STATES.YES) && (
        <div className="valentines__win">
          <Confetti type={gameState === GAME_STATES.YES ? 'hearts' : 'confetti'} />

          <div className="valentines__flip-container">
            {getOrderedTiles().map((tile, index) => (
              <div
                key={tile.id}
                className="valentines__flip-tile"
                style={{ animationDelay: `${index * 0.1}s` }}
              >
                <Tile tile={tile} isFlipped={true} />
              </div>
            ))}
          </div>

          {gameState === GAME_STATES.QUESTION && (
            <div className="valentines__question">
              <h1 className="valentines__question-text">
                Will you be my Valentine, Yuna?
              </h1>
              <div className="valentines__buttons">
                <button className="valentines__yes-btn" onClick={handleYes}>
                  Yes!
                </button>
                <button
                  className="valentines__no-btn"
                  onClick={handleNo}
                  style={{
                    transform: `translate(${noButtonPosition.x}px, ${noButtonPosition.y}px)`
                  }}
                >
                  No
                </button>
              </div>
            </div>
          )}

          {gameState === GAME_STATES.YES && (
            <div className="valentines__celebration">
              <h1 className="valentines__love-text">I Love You, Yuna!</h1>
              <div className="valentines__hearts">
                ❤️ 💕 💖 💗 💓 💝
              </div>
              <p className="valentines__love-message">You mean everything to me</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default Valentines;
