import React from 'react';
import Tile from './Tile';

const ROWS = 6;
const COLS = 8;

const Grid = ({ gridTiles, onDropToSlot, isDragging, onDragStart, onDragEnd }) => {
  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e, row, col) => {
    e.preventDefault();
    e.stopPropagation();
    const tileId = parseInt(e.dataTransfer.getData('tileId'), 10);
    const sourceType = e.dataTransfer.getData('sourceType');
    const sourceRow = e.dataTransfer.getData('sourceRow');
    const sourceCol = e.dataTransfer.getData('sourceCol');

    onDropToSlot(tileId, row, col, sourceType,
      sourceType === 'grid' ? parseInt(sourceRow, 10) : null,
      sourceType === 'grid' ? parseInt(sourceCol, 10) : null
    );
  };

  return (
    <div className={`grid ${isDragging ? 'grid--dragging' : ''}`}>
      {Array.from({ length: ROWS }, (_, row) => (
        <div key={row} className="grid__row">
          {Array.from({ length: COLS }, (_, col) => {
            const tile = gridTiles[row]?.[col];
            return (
              <div
                key={`${row}-${col}`}
                className={`grid__slot ${tile ? 'grid__slot--filled' : ''}`}
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, row, col)}
              >
                {tile && (
                  <Tile
                    tile={tile}
                    isFlipped={false}
                    sourceType="grid"
                    sourceRow={row}
                    sourceCol={col}
                    onDragStart={onDragStart}
                    onDragEnd={onDragEnd}
                  />
                )}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
};

export default Grid;
